        "status": "final",
        "code": {
          "text": "Previously reported HbA1c"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient recalls HbA1c as “8-something” approximately 6 months ago; reported from a previous GP, with no records available."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Telephone consultation observation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No observations or blood pressure available. Patient was speaking in full sentences, alert, coherent, and not short of breath."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Current threadworm symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No current threadworm symptoms."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Metformin"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "1 g twice daily"
          }
        ]
      }
    },
    {
